import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
    static StringTokenizer st = new StringTokenizer("");

    static String next() throws IOException {
        while (!st.hasMoreTokens()) st = new StringTokenizer(in.readLine());
        return st.nextToken();
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(next());
        HashMap<String, long[]> total = new HashMap<>();  // name -> {sum, count}
        for (int i = 0; i < n; i++) {
            String name = next();
            long grade = Long.parseLong(next());
            long[] t = total.computeIfAbsent(name, k -> new long[2]);
            t[0] += grade;
            t[1]++;
        }
        String best = null;
        long bs = 0, bc = 1;
        for (Map.Entry<String, long[]> e : total.entrySet()) {
            long[] t = e.getValue();
            // compare t[0] / t[1] > bs / bc by cross-multiplication
            if (best == null || t[0] * bc > bs * t[1]) {
                best = e.getKey();
                bs = t[0];
                bc = t[1];
            }
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	sum := map[string]int64{}
	cnt := map[string]int64{}
	order := []string{}
	for i := 0; i < n; i++ {
		sc.Scan()
		name := sc.Text()
		sc.Scan()
		grade, _ := strconv.ParseInt(sc.Text(), 10, 64)
		if _, ok := cnt[name]; !ok {
			order = append(order, name)
		}
		sum[name] += grade
		cnt[name]++
	}
	best := ""
	var bs, bc int64 = 0, 1
	for _, name := range order {
		s, c := sum[name], cnt[name]
		// compare s / c > bs / bc by cross-multiplication
		if best == "" || s*bc > bs*c {
			best, bs, bc = name, s, c
		}
	}
	fmt.Println(best)
}
